-- 05: водные объекты для экоконтроля (ФТ.GEO.2.1): озеро Камышловское и река Означенка.

-- note начинается с "водный объект" — карта красит их синим и использует как цели буферных зон.

INSERT INTO ku_mapinfra (key0, system__class_ku_mapinfra, ku_miname_mapinfra, ku_minote_mapinfra, ku_mipolygon_mapinfra)
SELECT (SELECT coalesce(max(key0),900000)+1 FROM ku_mapinfra), NULL, 'Озеро Камышловское', 'водный объект: озеро, рыбохозяйственный водоём', '{"type":"Polygon","coordinates":[[[71.447,54.9505],[71.454,54.952],[71.46,54.9515],[71.465,54.954],[71.469,54.9525],[71.47,54.949],[71.466,54.947],[71.461,54.9475],[71.456,54.9455],[71.451,54.944],[71.447,54.945],[71.445,54.9475],[71.447,54.9505]]]}'
WHERE NOT EXISTS (SELECT 1 FROM ku_mapinfra WHERE ku_miname_mapinfra = 'Озеро Камышловское');

INSERT INTO ku_mapinfra (key0, system__class_ku_mapinfra, ku_miname_mapinfra, ku_minote_mapinfra, ku_mipolygon_mapinfra)
